// Same picture, second name.
for (const [name, same] of [['kid', 'runner'], ['zap', 'bolt'], ['freeze', 'ice'], ['house', 'home'], ['chimney', 'factory-smoke'], ['lightning', 'bolt']]) ICONS[name] = ICONS[same];

const NS = 'http://www.w3.org/2000/svg';
const SPRITE = 'critter-run-icons';

// Adds the hidden sprite to the page once. icon() and iconHTML() call it for you.
export function installIcons(doc = document) {
  let sprite = doc.getElementById(SPRITE);
  if (sprite) return sprite;
  const symbols = Object.entries(ICONS).map(([name, d]) => `<symbol id="i-${name}" viewBox="0 0 512 512">${
    [].concat(d).map(p => `<path fill="currentColor" d="${p}"/>`).join('')}</symbol>`).join('');
  // Zero-specificity default size, so any page CSS for .ic wins.
  (doc.body || doc.documentElement).insertAdjacentHTML('afterbegin', `<svg id="${SPRITE}" xmlns="${NS}" aria-hidden="true" `
    + `style="position:absolute;width:0;height:0;overflow:hidden"><style>:where(svg.ic){width:1em;height:1em;flex-shrink:0}</style>${symbols}</svg>`);
  return doc.getElementById(SPRITE);
}

function check(name) {
  if (!Object.prototype.hasOwnProperty.call(ICONS, name)) console.warn(`Unknown icon "${name}"`);
  if (typeof document !== 'undefined') installIcons(document);
}

// <svg class="ic {cls}" aria-hidden="true"><use href="#i-{name}"/></svg> as an element.
export function icon(name, cls = '') {
  check(name);
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('class', `ic ${cls}`.trim());
  svg.setAttribute('aria-hidden', 'true');
  svg.appendChild(document.createElementNS(NS, 'use')).setAttribute('href', `#i-${name}`);
  return svg;
}

// Same as icon(), as an HTML string for templates.
export function iconHTML(name, cls = '') {
  check(name);
  return `<svg class="${`ic ${cls}`.trim()}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
}
